/bin/zsh -lc "mkdir -p src test; cat > src/server.mjs <<'EOF'
import http from 'node:http'; import {promises as fs} from 'node:fs'; import path from 'node:path'; import crypto from 'node:crypto';
const file=path.resolve(process.env.DATA_FILE||'tasks.json'); let tasks=[]; let queue=Promise.resolve();
async function load(){try{const s=JSON.parse(await fs.readFile(file,'utf8')); if("'!s||!Array.isArray(s.tasks)) throw Error('"'invalid store'); tasks=s.tasks;}catch(e){if(e.code==='ENOENT'){await fs.mkdir(path.dirname(file),{recursive:true}); tasks=[];} else throw e;}}
async function persist(next){await fs.mkdir(path.dirname(file),{recursive:true}); const tmp=file+'.tmp-'+crypto.randomUUID(); const h=await fs.open(tmp,'w'); try{await h.writeFile(JSON.stringify({tasks:next})); await h.sync();}finally{await h.close();} await fs.rename(tmp,file);}
const json=(res,status,obj)=>{const b=obj?JSON.stringify(obj):''; res.writeHead(status,obj?{'content-type':'application/json'}:{});res.end(b)};
function body(req){return new Promise((resolve,reject)=>{let d='';req.on('data',c=>{d+=c;if(d.length>1e6) reject(Error('body too large'))});req.on('end',()=>{try{resolve(d?JSON.parse(d):{})}catch{reject(Error('malformed JSON'))}});req.on('error',reject)})}
async function main(){await load(); const server=http.createServer(async(req,res)=>{try{const u=new URL(req.url,'http://x'), parts=u.pathname.split('/').filter(Boolean); if(req.method==='GET'&&u.pathname==='/health') return json(res,200,{status:'ok'}); if("'!parts.length||parts[0]!=='"'tasks'||parts.length>2) return json(res,404,{error:'not found'}); const id=parts[1]; if(req.method==='GET'){if("'!id)return json(res,200,{tasks}); const t=tasks.find(x=>x.id===decodeURIComponent(id)); return t?json(res,200,t):json(res,404,{error:'"'not found'})} if(req.method==='POST'&&"'!id){let x;try{x=await body(req)}catch(e){return json(res,400,{error:e.message})} if(typeof x.title!=='"'string'||"'!x.title.trim()) return json(res,400,{error:'"'invalid title'}); const t={id:crypto.randomUUID(),title:x.title,status:'pending'}; return queue=queue.then(async()=>{const n=[...tasks,t];await persist(n);tasks=n;json(res,201,t)}).catch(e=>json(res,500,{error:e.message}))} if((req.method==='PATCH'||req.method==='DELETE')&&id){const i=tasks.findIndex(x=>x.id===decodeURIComponent(id));if(i<0)return json(res,404,{error:'not found'}); if(req.method==='PATCH'){let x;try{x=await body(req)}catch(e){return json(res,400,{error:e.message})}if("'!['"'pending','done'].includes(x.status))return json(res,400,{error:'invalid status'});return queue=queue.then(async()=>{const n=tasks.map((t,j)=>j===i?{...t,status:x.status}:t);await persist(n);tasks=n;json(res,200,n[i])}).catch(e=>json(res,500,{error:e.message}))} return queue=queue.then(async()=>{const n=tasks.filter((_,j)=>j"'!==i);await persist(n);tasks=n;json(res,204)}).catch(e=>json(res,500,{error:e.message}))} return json(res,405,{error:'"'method not allowed'})}catch(e){json(res,500,{error:e.message})}}); server.listen(Number(process.env.PORT||3000),()=>console.log('LISTENING '+server.address().port));}
main().catch(e=>{console.error(e.message);process.exit(1)});
EOF
cat > package.json <<'EOF'
{\"type\":\"module\",\"scripts\":{\"start\":\"node src/server.mjs\",\"test\":\"node --test\"}}
EOF
cat > test/server.test.mjs <<'EOF'
import test from 'node:test';import assert from 'node:assert';import {mkdtemp,rm} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import {spawn} from 'node:child_process';
async function app(){const d=await mkdtemp(path.join(os.tmpdir(),'tsk-')),p=path.join(d,'db.json');const c=spawn(process.execPath,['src/server.mjs'],{env:{...process.env,DATA_FILE:p,PORT:'0'}});let port=await new Promise(r=>c.stdout.once('data',x=>r(+x.toString().split(' ')[1])));let base='http://127.0.0.1:'+port;return {base,c,d}}
test('crud and validation',async()=>{const a=await app();let r=await fetch(a.base+'/health');assert.equal(r.status,200);r=await fetch(a.base+'/tasks',{method:'POST',body:'{}'});assert.equal(r.status,400);r=await fetch(a.base+'/tasks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:'x'})});let t=await r.json();assert.equal(r.status,201);r=await fetch(a.base+'/tasks/'+t.id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status:'done'})});assert.equal((await r.json()).status,'done');a.c.kill();await rm(a.d,{recursive:true,force:true})});
EOF
npm test > test-results.txt 2>&1"
